const OQ = (p: string, c: string, o: [string, string, string, string], e: string): OutputQSpec => ({ p, c, o, a: 0, e });
const S = (title: string, desc: string, lessons: [LessonSpec, LessonSpec, LessonSpec, LessonSpec], out: [OutputQSpec, OutputQSpec]): SectionSpec => ({ title, desc, lessons, out });

